export function wartimeDuration(input={}){const f={...wartimeDefaults,...input};return wartimeStages.reduce((n,s)=>n+(f.wartimeSceneDurations[s.id]??s.duration),0)/f.wartimeRate;}
export function wartimeSourceToLocal(source,input={}){const f={...wartimeDefaults,...input};let n=0;for(const s of wartimeStages){const d=f.wartimeSceneDurations[s.id]??s.duration;if(source<=s.to)return(n+d*clamp((source-s.from)/s.duration))/f.wartimeRate;n+=d;}return n/f.wartimeRate;}
export function wartimeState(age,input={}){const f={...wartimeDefaults,...input};let n=0,row=wartimeStages.at(-1),phase=1;for(const s of wartimeStages){const d=f.wartimeSceneDurations[s.id]??s.duration;if(age*f.wartimeRate<n+d){row=s;phase=clamp((age*f.wartimeRate-n)/d);break;}n+=d;}return{id:row.id,label:row.label,source:mix(row.from,row.to,phase),phase,local:age,active:f.wartimeEnabled&&age>=0&&age<=wartimeDuration(f)};}
