function layer(c,f,id,t,r,draw,o={}){const e=f.wartimeLayerEdits[id]||{};if(e.visible===false)return;const m=sampleObjectMotion((t-475)/f.wartimeRate,e.motion||{}),[x,y,w,h]=r,z=(1+f.wartimeCameraZoom);c.save();c.translate(x+w/2+(e.x||0)+m.x-f.wartimeCameraX/(e.depth||2),y+h/2+(e.y||0)+m.y-f.wartimeCameraY/(e.depth||2));c.rotate(((e.rotation||0)+(o.rotation||0)+m.rotation)*Math.PI/180);c.scale((e.scale??1)*m.scale*z,(e.scale??1)*m.scale*z);c.globalAlpha*=clamp((e.opacity??1)*(o.alpha??1)*m.opacity);c.filter=`blur(${(e.blur||0)+(o.blur||0)}px) brightness(${(e.brightness??1)*(o.light??1)}) grayscale(${o.mono||0})`;draw(-w/2,-h/2,w,h);recordSceneAsset(c,{id:'wartime:'+id,editKey:id,assetSlot:wartimeLayerCatalog.find(l=>l.id===id)?.slot,name:id,kind:'wartime'},[-w/2,-h/2,w,h]);c.restore();}
