function hall(c,images,f,t){plate(c,images,f,'wartHall',t,1.15+.05*Math.sin((t-483.5)*.3));layer(c,f,'silhouettes',t,[0,0,960,540],()=>{for(let i=0;i<8;i++){const age=t-483.5,d=1+i%3*.3,x=((i*237+age*(i%2?65:-48)+2000)%1500)-750,y=40+i%3*30;c.save();c.translate(x,y);c.scale(d,d);c.filter='blur(4px)';c.fillStyle='#03070bec';c.beginPath();c.ellipse(0,-100,19,27,0,0,Math.PI*2);c.fill();c.beginPath();c.moveTo(-27,-73);c.lineTo(30,-73);c.lineTo(50,180);c.lineTo(-54,180);c.closePath();c.fill();c.restore();}});if(t>=488.1){const q=span(t,488.1,490.2);sprite(c,images,f,'wartBrothers',t,[-640+q*710,50,820,0],{mono:.6});}if(t<484.2){c.fillStyle=`rgba(0,0,0,${1-span(t,483.5,484.2)})`;c.fillRect(0,0,960,540);}}
